package ratelimit

import (
	"sync"
	"testing"
	"time"
)

type fakeClock struct {
	mu  sync.Mutex
	now time.Time
}

func newFakeClock() *fakeClock {
	return &fakeClock{now: time.Date(2024, 1, 1, 0, 0, 0, 0, time.UTC)}
}

func (c *fakeClock) Now() time.Time {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.now
}

func (c *fakeClock) Advance(d time.Duration) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.now = c.now.Add(d)
}

func TestNewValidation(t *testing.T) {
	clock := newFakeClock()
	tests := []struct {
		name     string
		capacity int
		rate     float64
		clock    Clock
		wantErr  bool
	}{
		{"nil clock", 5, 1, nil, true},
		{"zero capacity", 0, 1, clock, true},
		{"negative capacity", -1, 1, clock, true},
		{"zero rate", 5, 0, clock, true},
		{"negative rate", 5, -1, clock, true},
		{"valid", 5, 1, clock, false},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			b, err := New(tt.capacity, tt.rate, tt.clock)
			if (err != nil) != tt.wantErr {
				t.Fatalf("err = %v, wantErr = %v", err, tt.wantErr)
			}
			if !tt.wantErr && b == nil {
				t.Fatal("expected bucket")
			}
		})
	}
}

type step struct {
	advance time.Duration
	n       int
	want    bool
}

func TestAllowN(t *testing.T) {
	tests := []struct {
		name     string
		capacity int
		rate     float64
		steps    []step
	}{
		{
			name:     "drains and refills",
			capacity: 5,
			rate:     1,
			steps: []step{
				{0, 5, true},
				{0, 1, false},
				{2 * time.Second, 2, true},
				{0, 1, false},
			},
		},
		{
			name:     "refill caps at capacity",
			capacity: 3,
			rate:     10,
			steps: []step{
				{time.Hour, 3, true},
				{0, 1, false},
			},
		},
		{
			name:     "zero and negative",
			capacity: 2,
			rate:     1,
			steps: []step{
				{0, 0, true},
				{0, -1, false},
				{0, 2, true},
			},
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			clock := newFakeClock()
			b, err := New(tt.capacity, tt.rate, clock)
			if err != nil {
				t.Fatal(err)
			}
			for i, s := range tt.steps {
				clock.Advance(s.advance)
				if got := b.AllowN(s.n); got != s.want {
					t.Fatalf("step %d: AllowN(%d) = %v, want %v", i, s.n, got, s.want)
				}
			}
		})
	}
}

func TestConcurrentAllow(t *testing.T) {
	clock := newFakeClock()
	b, err := New(100, 0, clock) // rate must be > 0; use tiny rate instead
	if err == nil {
		_ = b
	}
	b, err = New(100, 0.0001, clock)
	if err != nil {
		t.Fatal(err)
	}
	var wg sync.WaitGroup
	allowed := make(chan bool, 200)
	for i := 0; i < 200; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			allowed <- b.Allow()
		}()
	}
	wg.Wait()
	close(allowed)
	count := 0
	for ok := range allowed {
		if ok {
			count++
		}
	}
	if count != 100 {
		t.Fatalf("allowed = %d, want 100", count)
	}
}
